typedef unsigned int MemSize;
typedef unsigned int MemFlags;

enum MemoryBlockTypes {
    mbtUsed = 1
};

struct MemFlagDWord {
    MemFlags magic : 16;
    MemFlags heapid : 8;
    MemFlags flags : 8;
};

class MemBlockInfo {
public:
    MemBlockInfo *prev;
    MemBlockInfo *next;
    MemBlockInfo *prevoftype;
    MemBlockInfo *nextoftype;
    MemSize size;
    MemFlagDWord flags;
    MemFlags blockid;
};

class Heap {
    MemBlockInfo *fullhead;
    MemBlockInfo *fulltail;
    MemBlockInfo *usedhead;
    MemBlockInfo *usedtail;
    MemBlockInfo *freehead;
    MemBlockInfo *freetail;
    MemSize heapsize;
    void *heapstart;
    MemSize allocatedblocks;
    MemSize minalloc;
    MemSize minalign;
    MemSize lastalloc;
    MemFlags heapid;

public:
    MemFlags GetHeapID() const { return heapid; }
    MemSize HeaderSize() const;
    void MoveFreeToUsed(MemBlockInfo *block);
    void MoveUsedToFree(MemBlockInfo *block);
    void SetBlockSentry(MemBlockInfo *block);
    void MergeBlock(MemBlockInfo *block);
};

__asm__(".equ HeaderSize__C4Heap, 0x002AB370");
__asm__(".equ MoveFreeToUsed__4HeapP12MemBlockInfo, 0x002AC0C8");
__asm__(".equ MoveUsedToFree__4HeapP12MemBlockInfo, 0x002ABFF0");
__asm__(".equ SetBlockSentry__4HeapP12MemBlockInfo, 0x002AB678");

void Heap::MergeBlock( MemBlockInfo *block )
{
	if ( (block->flags.flags & mbtUsed) != (block->next->flags.flags & mbtUsed)  )
	{
		if ( (block->flags.flags & mbtUsed) )
		{
			MoveFreeToUsed(block->next);
		}
		else
		{
			MoveUsedToFree(block->next);
		}
	}

	block->next->flags.magic = 0;
	block->next->flags.heapid = 0xFF;

	block->size += block->next->size + HeaderSize();

	MemBlockInfo *nblock=block->next;

	MemBlockInfo *prev=nblock->prev;
	MemBlockInfo *next=nblock->next;
	if ( prev )
	{
		prev->next=next;
	}
	else
	{
		fullhead=next;
	}
	if ( next )
	{
		next->prev=prev;
	}
	else
	{
		fulltail=block;
	}

	MemBlockInfo *prevoftype=nblock->prevoftype;
	MemBlockInfo *nextoftype=nblock->nextoftype;
	if ( prevoftype )
	{
		prevoftype->nextoftype=nextoftype;
	}
	else
	{
		if ( (block->flags.flags & mbtUsed) )
		{
			usedhead=nextoftype;
		}
		else
		{
			freehead=nextoftype;
		}
	}
	if ( nextoftype )
	{
		nextoftype->prevoftype=prevoftype;
	}
	else
	{
		if ( (block->flags.flags & mbtUsed) )
		{
			usedtail=prevoftype;
		}
		else
		{
			freetail=prevoftype;
		}
	}
	block->flags.magic = 0x7E07;
	block->flags.heapid = GetHeapID();
	SetBlockSentry(block);
}
